package app.velyntora.windows.app;
import art.velyntora.core.*;
import app.velyntora.windows.canvas.CanvasPanel;
import app.velyntora.windows.layers.LayersPanel;
import app.velyntora.windows.document.DocumentIO;
import app.velyntora.windows.tools.Tool;
import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.nio.file.*;
import java.util.concurrent.Callable;
public final class EditorWindow extends JFrame {
 public final CanvasPanel canvas;private final LayersPanel layers;private final JLabel status=new JLabel(" ");private final JFrame home;private long clean;private Path project;private int[] clipboard;
 public EditorWindow(JFrame home){super("Velyntora Drawing");this.home=home;clean=DrawingView.nativeRevision();setSize(1360,850);setMinimumSize(new Dimension(900,600));setLocationRelativeTo(null);setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);
  canvas=new CanvasPanel(this::status);layers=new LayersPanel(this::refresh);setLayout(new BorderLayout());add(canvas,BorderLayout.CENTER);add(layers,BorderLayout.EAST);add(status,BorderLayout.SOUTH);setJMenuBar(menus());add(toolbar(),BorderLayout.NORTH);
  JPanel tools=new JPanel(new GridLayout(0,2,2,2));tools.setPreferredSize(new Dimension(200,650));ButtonGroup group=new ButtonGroup();for(Tool tool:Tool.values()){JToggleButton button=new JToggleButton(tool.label);button.setSelected(tool==Tool.BRUSH);group.add(button);button.addActionListener(e->{canvas.commitCurve();canvas.tool=tool;});tools.add(button);}add(new JScrollPane(tools),BorderLayout.WEST);
  addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){if(protect()){dispose();if(home!=null)home.setVisible(true);}}});
  bind("ctrl Z",()->{canvas.undo();refresh();});bind("ctrl Y",()->{DrawingView.nativeRedo();refresh();});bind("ctrl S",this::save);bind("ctrl O",this::open);bind("ctrl N",this::newDocument);bind("ENTER",canvas::commitCurve);bind("ESCAPE",canvas::cancelCurve);bind("DELETE",canvas::deleteSelection);bind("ctrl A",()->{canvas.selectAll();});bind("ctrl D",canvas::clearSelection);bind("ctrl C",this::copy);bind("ctrl V",this::paste);
 }
 private void bind(String key,Runnable action){getRootPane().getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW).put(KeyStroke.getKeyStroke(key),key);getRootPane().getActionMap().put(key,new AbstractAction(){public void actionPerformed(ActionEvent e){action.run();}});}
 private JComponent toolbar(){JToolBar bar=new JToolBar();bar.setFloatable(false);JButton primary=new JButton("Color");primary.addActionListener(e->{Color color=JColorChooser.showDialog(this,"Color principal",new Color(canvas.color,true));if(color!=null){canvas.color=color.getRGB();primary.setBackground(color);}});bar.add(primary);JButton secondary=new JButton("Secundario");secondary.addActionListener(e->{Color color=JColorChooser.showDialog(this,"Color secundario",new Color(canvas.secondary,true));if(color!=null)canvas.secondary=color.getRGB();});bar.add(secondary);bar.add(new JLabel(" Ancho "));JSpinner size=new JSpinner(new SpinnerNumberModel(8,1,300,1));size.addChangeListener(e->canvas.size=(int)size.getValue());bar.add(size);bar.add(new JLabel(" Opacidad "));JSlider opacity=new JSlider(0,100,100);opacity.setPreferredSize(new Dimension(100,30));opacity.addChangeListener(e->canvas.opacity=opacity.getValue()/100f);bar.add(opacity);
  JCheckBox filled=new JCheckBox("Relleno");filled.addActionListener(e->canvas.filled=filled.isSelected());bar.add(filled);bar.add(new JLabel(" Tolerancia "));JSpinner tolerance=new JSpinner(new SpinnerNumberModel(24,0,255,1));tolerance.addChangeListener(e->canvas.tolerance=(int)tolerance.getValue());bar.add(tolerance);
  JComboBox<Object> presets=new JComboBox<>();presets.addItem("Clásico");for(var preset:BrushPresets.ALL)presets.addItem(preset);presets.setMaximumSize(new Dimension(260,30));presets.addActionListener(e->{Object p=presets.getSelectedItem();canvas.preset=p instanceof BrushPresets.Preset?(BrushPresets.Preset)p:null;});bar.add(presets);return bar;
 }
 private JMenuBar menus(){JMenuBar bar=new JMenuBar();JMenu file=new JMenu("Archivo");item(file,"Nuevo",this::newDocument);item(file,"Abrir imagen / proyecto",this::open);item(file,"Guardar proyecto",this::save);item(file,"Exportar imagen",this::export);item(file,"Volver al inicio",()->dispatchEvent(new WindowEvent(this,WindowEvent.WINDOW_CLOSING)));bar.add(file);
  JMenu edit=new JMenu("Editar");item(edit,"Deshacer",()->{canvas.undo();refresh();});item(edit,"Rehacer",()->{DrawingView.nativeRedo();refresh();});item(edit,"Copiar",this::copy);item(edit,"Pegar",this::paste);item(edit,"Borrar selección",canvas::deleteSelection);item(edit,"Deseleccionar",canvas::clearSelection);bar.add(edit);
  JMenu view=new JMenu("Ver");item(view,"Ajustar lienzo",canvas::fit);item(view,"100%",()->canvas.setZoom(1,new Point(canvas.getWidth()/2,canvas.getHeight()/2)));item(view,"Girar 15°",()->{canvas.rotation+=Math.PI/12;canvas.repaint();});item(view,"Restablecer rotación",()->{canvas.rotation=0;canvas.repaint();});bar.add(view);
  JMenu image=new JMenu("Imagen");item(image,"Cambiar tamaño",()->resize(true));item(image,"Tamaño del lienzo",()->resize(false));item(image,"Voltear horizontal",()->effect(()->DrawingView.nativeFlipActiveHorizontal()));item(image,"Voltear vertical",()->effect(()->DrawingView.nativeFlipActiveVertical()));item(image,"Girar 90°",()->effect(()->DrawingView.nativeRotateActive90(true)));bar.add(image);
  JMenu effects=new JMenu("Ajustes / Efectos");item(effects,"Invertir colores",()->effect(()->DrawingView.nativeInvertActiveColors()));item(effects,"Escala de grises",()->effect(()->DrawingView.nativeGrayscaleActive()));item(effects,"Sepia",()->effect(()->DrawingView.nativeSepiaActive()));item(effects,"Brillo",()->parameter("Brillo",-100,100,0,v->DrawingView.nativeBrightnessActive(v)));item(effects,"Contraste",()->parameter("Contraste",-100,100,0,v->DrawingView.nativeContrastActive(v)));item(effects,"Saturación",()->parameter("Saturación",-100,100,0,v->DrawingView.nativeSaturationActive(v)));item(effects,"Tono",()->parameter("Tono",0,360,0,v->DrawingView.nativeHueRotateActive(v)));item(effects,"Umbral",()->parameter("Umbral",0,255,128,v->DrawingView.nativeThresholdActive(v)));item(effects,"Desenfoque",()->parameter("Radio",1,32,4,v->DrawingView.nativeBlur(0,v,0,50,50)));item(effects,"Pixelar",()->parameter("Tamaño",1,100,8,v->DrawingView.nativeEffect(4,v)));bar.add(effects);
  JMenu help=new JMenu("Ayuda");item(help,"Acerca de",()->JOptionPane.showMessageDialog(this,"Velyntora Drawing · Piloto Windows x64\nPowered By Zaskar Startup\nRueda: zoom · Alt+rueda: rotar · Botón central: desplazar\nLínea/Curva: arrastra extremos, añade un punto y pulsa Enter.\nClonar: Alt+clic elige el origen.\nEste piloto no tiene todavía paridad completa con Android."));bar.add(help);return bar;
 }
 private void item(JMenu menu,String text,Runnable action){JMenuItem item=new JMenuItem(text);item.addActionListener(e->{try{action.run();}catch(Throwable error){JOptionPane.showMessageDialog(this,error.toString(),"Velyntora Drawing",JOptionPane.ERROR_MESSAGE);}});menu.add(item);}
 private void status(){if(DrawingView.nativeWidth()<1)return;status.setText("  "+DrawingView.nativeWidth()+" × "+DrawingView.nativeHeight()+" px   |   "+Math.round(canvas.zoom*100)+"%   |   "+canvas.tool.label+"   |   Enter: confirmar curva");setTitle("Velyntora Drawing · "+(project==null?"[No guardado]":project.getFileName())+(DrawingView.nativeRevision()!=clean?" *":""));}
 public void refresh(){canvas.refresh();layers.refresh();status();}
 public boolean newDocument(){if(!protect())return false;JSpinner width=new JSpinner(new SpinnerNumberModel(1200,1,6000,1)),height=new JSpinner(new SpinnerNumberModel(800,1,6000,1));JPanel form=new JPanel(new GridLayout(0,2));form.add(new JLabel("Ancho (px)"));form.add(width);form.add(new JLabel("Alto (px)"));form.add(height);if(JOptionPane.showConfirmDialog(this,form,"Crear ilustración",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return false;if(!DrawingView.nativeCreate((int)width.getValue(),(int)height.getValue()))throw new IllegalStateException("No se pudo crear el lienzo");project=null;clean=DrawingView.nativeRevision();canvas.clearSelection();refresh();SwingUtilities.invokeLater(canvas::fit);return true;}
 public boolean open(){if(!protect())return false;JFileChooser chooser=new JFileChooser();if(chooser.showOpenDialog(this)!=JFileChooser.APPROVE_OPTION)return false;try{openPath(chooser.getSelectedFile().toPath());return true;}catch(Exception error){JOptionPane.showMessageDialog(this,error.toString());return false;}}
 public void openPath(Path path)throws Exception{DocumentIO.open(path);project=path.toString().toLowerCase().endsWith(".vlycore")?path:null;clean=DrawingView.nativeRevision();canvas.clearSelection();refresh();SwingUtilities.invokeLater(canvas::fit);}
 public void save(){canvas.commitCurve();try{if(project==null){JFileChooser chooser=new JFileChooser();chooser.setSelectedFile(new java.io.File("dibujo.vlycore"));if(chooser.showSaveDialog(this)!=JFileChooser.APPROVE_OPTION)return;project=chooser.getSelectedFile().toPath();if(!project.toString().endsWith(".vlycore"))project=Path.of(project+".vlycore");}DocumentIO.saveProject(project);clean=DrawingView.nativeRevision();status();}catch(Exception error){JOptionPane.showMessageDialog(this,error.toString());}}
 private void export(){canvas.commitCurve();JFileChooser chooser=new JFileChooser();chooser.setSelectedFile(new java.io.File("ilustracion.png"));if(chooser.showSaveDialog(this)!=JFileChooser.APPROVE_OPTION)return;try{DocumentIO.export(chooser.getSelectedFile().toPath());}catch(Exception error){JOptionPane.showMessageDialog(this,error.toString());}}
 private boolean protect(){if(DrawingView.nativeWidth()<1||DrawingView.nativeRevision()==clean)return true;int answer=JOptionPane.showConfirmDialog(this,"¿Guardar los cambios del dibujo?","Cambios sin guardar",JOptionPane.YES_NO_CANCEL_OPTION);if(answer==JOptionPane.YES_OPTION){save();return DrawingView.nativeRevision()==clean;}return answer==JOptionPane.NO_OPTION;}
 private void resize(boolean scale){String value=JOptionPane.showInputDialog(this,"Ancho × alto (máximo 6000 × 6000)",DrawingView.nativeWidth()+"x"+DrawingView.nativeHeight());if(value==null)return;try{String[] sides=value.toLowerCase().replace(" ","").split("[x×]");if(!DrawingView.nativeResizeDocumentOptions(Integer.parseInt(sides[0]),Integer.parseInt(sides[1]),scale,true,4))throw new IllegalArgumentException("Tamaño no válido");canvas.clearSelection();refresh();}catch(Exception e){JOptionPane.showMessageDialog(this,e.toString());}}
 private void copy(){clipboard=canvas.copySelection();}
 private void paste(){if(clipboard!=null){DrawingView.nativePasteSelection(clipboard,0,0);refresh();}}
 private interface IntEffect{boolean apply(int value);}
 private void parameter(String label,int min,int max,int initial,IntEffect action){JSlider slider=new JSlider(min,max,initial);if(JOptionPane.showConfirmDialog(this,slider,label,JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)effect(()->action.apply(slider.getValue()));}
 private void effect(Callable<Boolean> work){canvas.commitCurve();DrawingView.nativeSetEffectSelection(canvas.selection);setCursor(Cursor.getPredefinedCursor(Cursor.WAIT_CURSOR));setEnabled(false);new SwingWorker<Boolean,Void>(){protected Boolean doInBackground()throws Exception{return work.call();}protected void done(){setEnabled(true);setCursor(Cursor.getDefaultCursor());try{if(!get())throw new IllegalStateException("La operación no se pudo completar");}catch(Exception error){JOptionPane.showMessageDialog(EditorWindow.this,error.toString());}refresh();}}.execute();}
}
